tools.script_template:
const page = await browser.getPage('bench-{case_id}');
await page.goto({url!r}, {{ waitUntil: 'domcontentloaded', timeout: {timeout_seconds}000 }});
await page.locator({search_selector!r}).first().fill({search_value!r}, {{ timeout: 8000 }});
if ({submit_selector!r}) {{
  await page.locator({submit_selector!r}).first().click({{ timeout: 8000 }});
}} else {{
  await page.locator({search_selector!r}).first().press('Enter');
}}
await page.waitForTimeout(2500);
if ({result_selector!r}) {{
  await page.locator({result_selector!r}).first().click({{ timeout: 10000 }}).catch(() => null);
  await page.waitForTimeout(2500);
}}
if ({follow_selector!r}) {{
  await page.locator({follow_selector!r}).first().click({{ timeout: 10000 }}).catch(() => null);
  await page.waitForTimeout(2500);
}}
const text = await page.locator('body').innerText({{ timeout: 8000 }});
const links = await page.locator('a').evaluateAll(els => els.slice(0, 80).map(a => ({{ text: a.innerText, href: a.href }})));
console.log(JSON.stringify({{ url: page.url(), title: await page.title(), task: {prompt!r}, text: text.slice(0, 18000), links }}, null, 2));

tools.stdin_template:
import json
new_tab({url!r})
wait_for_load(20)
script = r'''
(async () => {{
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pick = sel => sel ? document.querySelector(sel) : null;
  const input = pick({search_selector!r});
  if (!input) return {{ error: 'missing search input', url: location.href, title: document.title, text: document.body ? document.body.innerText.slice(0, 18000) : '' }};
  input.focus();
  input.value = {search_value!r};
  input.dispatchEvent(new Event('input', {{ bubbles: true }}));
  input.dispatchEvent(new Event('change', {{ bubbles: true }}));
  const submit = pick({submit_selector!r});
  if (submit) submit.click();
  else if (input.form && input.form.requestSubmit) input.form.requestSubmit();
  else input.dispatchEvent(new KeyboardEvent('keydown', {{ key: 'Enter', code: 'Enter', bubbles: true }}));
  await sleep(2500);
  const result = pick({result_selector!r});
  if (result) {{ result.click(); await sleep(2500); }}
  const follow = pick({follow_selector!r});
  if (follow) {{ follow.click(); await sleep(2500); }}
  const links = Array.from(document.querySelectorAll('a')).slice(0, 80).map(a => ({{ text: a.innerText, href: a.href }}));
  return {{ url: location.href, title: document.title, task: {prompt!r}, text: document.body ? document.body.innerText.slice(0, 18000) : '', links }};
}})()
'''
result = js(script) or {{}}
print(json.dumps(result, indent=2))
